"use client";

import { useState, useEffect } from "react";
import { useLanguage } from "@/contexts/LanguageContext";

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const { language, setLanguage } = useLanguage();

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const navLinks = [
    { label: language === 'es' ? 'Inicio' : 'Home', href: '#hero' },
    { label: language === 'es' ? 'Servicios' : 'Services', href: '#services' },
    { label: language === 'es' ? 'Capacidades' : 'Capabilities', href: '#capabilities' },
    { label: language === 'es' ? 'Clientes' : 'Clients', href: '#clients' },
    { label: language === 'es' ? 'Testimonios' : 'Testimonials', href: '#testimonials' },
  ];

  const navStyle: React.CSSProperties = {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    zIndex: 100,
    transition: 'all 0.3s ease',
    backgroundColor: scrolled ? 'rgba(10,10,10,0.92)' : 'transparent',
    backdropFilter: scrolled ? 'blur(20px)' : 'none',
    borderBottom: scrolled ? '1px solid rgba(255,255,255,0.06)' : '1px solid transparent',
  };

  const linkStyle: React.CSSProperties = {
    color: '#838383',
    textDecoration: 'none',
    fontSize: '0.85rem',
    fontWeight: '600',
    letterSpacing: '1px',
    textTransform: 'uppercase',
    transition: 'color 0.2s ease',
    cursor: 'pointer',
  };

  return (
    <nav style={navStyle}>
      <div className="mxd-container">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: '72px' }}>

          {/* Logo */}
          <a href="#hero" style={{ textDecoration: 'none' }}>
            <span style={{ fontSize: '1.4rem', fontWeight: '900', color: '#FAF7F6', letterSpacing: '-0.03em' }}>
              CODE<span style={{ color: '#10B981' }}>CRAFTT</span>
            </span>
          </a>

          {/* Desktop Links */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '36px' }} className="rayo-nav-desktop">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                style={linkStyle}
                onMouseEnter={(e) => { e.currentTarget.style.color = '#FAF7F6'; }}
                onMouseLeave={(e) => { e.currentTarget.style.color = '#838383'; }}
              >
                {link.label}
              </a>
            ))}
          </div>

          {/* Right Controls */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            {/* Language Toggle */}
            <button
              onClick={() => setLanguage(language === 'en' ? 'es' : 'en')}
              style={{
                background: 'transparent',
                border: '1px solid rgba(255,255,255,0.15)',
                color: '#838383',
                borderRadius: '100px',
                padding: '6px 14px',
                fontSize: '0.75rem',
                fontWeight: '700',
                letterSpacing: '2px',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
              }}
              onMouseEnter={(e) => { e.currentTarget.style.borderColor = '#10B981'; e.currentTarget.style.color = '#10B981'; }}
              onMouseLeave={(e) => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.15)'; e.currentTarget.style.color = '#838383'; }}
            >
              {language === 'en' ? 'ES' : 'EN'}
            </button>

            {/* CTA */}
            <a
              href="#contact"
              style={{
                backgroundColor: '#10B981',
                color: '#161616',
                textDecoration: 'none',
                padding: '10px 24px',
                borderRadius: '100px',
                fontSize: '0.8rem',
                fontWeight: '900',
                letterSpacing: '1px',
                textTransform: 'uppercase',
                transition: 'all 0.2s ease',
                display: 'inline-block',
              }}
              onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#059669'; e.currentTarget.style.transform = 'scale(1.04)'; }}
              onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#10B981'; e.currentTarget.style.transform = 'scale(1)'; }}
            >
              {language === 'es' ? 'Hablemos' : "Let's Talk"}
            </a>

            {/* Hamburger */}
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '4px', display: 'none' }}
              className="rayo-hamburger"
              aria-label="Menu"
            >
              <div style={{ width: '22px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
                <span style={{ display: 'block', height: '2px', backgroundColor: mobileOpen ? '#10B981' : '#FAF7F6', transition: 'all 0.3s', transform: mobileOpen ? 'rotate(45deg) translateY(7px)' : 'none' }} />
                <span style={{ display: 'block', height: '2px', backgroundColor: '#FAF7F6', opacity: mobileOpen ? 0 : 1, transition: 'all 0.3s' }} />
                <span style={{ display: 'block', height: '2px', backgroundColor: mobileOpen ? '#10B981' : '#FAF7F6', transition: 'all 0.3s', transform: mobileOpen ? 'rotate(-45deg) translateY(-7px)' : 'none' }} />
              </div>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {mobileOpen && (
        <div style={{
          backgroundColor: '#0a0a0a',
          borderTop: '1px solid rgba(255,255,255,0.06)',
          padding: '24px 40px',
          display: 'flex',
          flexDirection: 'column',
          gap: '20px',
        }}>
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              onClick={() => setMobileOpen(false)}
              style={{ ...linkStyle, fontSize: '1.1rem' }}
            >
              {link.label}
            </a>
          ))}
          <a
            href="#contact"
            onClick={() => setMobileOpen(false)}
            style={{
              backgroundColor: '#10B981',
              color: '#161616',
              textDecoration: 'none',
              padding: '14px 24px',
              borderRadius: '100px',
              fontSize: '0.9rem',
              fontWeight: '900',
              letterSpacing: '1px',
              textTransform: 'uppercase',
              textAlign: 'center',
              marginTop: '8px',
            }}
          >
            {language === 'es' ? 'Hablemos' : "Let's Talk"}
          </a>
        </div>
      )}

      <style>{`
        @media (max-width: 768px) {
          .rayo-nav-desktop { display: none !important; }
          .rayo-hamburger { display: block !important; }
        }
      `}</style>
    </nav>
  );
}
